mapper.delete:
DELETE FROM user_follow
WHERE follower_id = #{followerId}
  AND followee_id = #{followeeId}

mapper.select:
SELECT COUNT(1) > 0
FROM user_follow
WHERE follower_id = #{followerId}
  AND followee_id = #{followeeId}

mapper.delete:
DELETE FROM user_block
WHERE blocker_id = #{blockerId}
  AND blocked_id = #{blockedId}

mapper.select:
SELECT COUNT(1) > 0
FROM user_follow f1
WHERE f1.follower_id = #{userA}
  AND f1.followee_id = #{userB}
  AND EXISTS (
      SELECT 1 FROM user_follow f2
      WHERE f2.follower_id = #{userB}
        AND f2.followee_id = #{userA}
  )

SELECT u.id, u.username, u.avatar, u.bio
FROM sys_user u
WHERE EXISTS (
    SELECT 1 FROM user_follow f1
    WHERE f1.follower_id = #{userId} AND f1.followee_id = u.id
)
  AND EXISTS (
    SELECT 1 FROM user_follow f2
    WHERE f2.follower_id = u.id AND f2.followee_id = #{userId}
)
  AND NOT EXISTS (
    SELECT 1 FROM user_block b
    WHERE (b.blocker_id = #{userId} AND b.blocked_id = u.id)
       OR (b.blocker_id = u.id   AND b.blocked_id = #{userId})
)
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE sys_user
SET following_count = following_count + #{delta}
WHERE id = #{userId}
  AND following_count + #{delta} >= 0

UPDATE sys_user
SET follower_count = follower_count + #{delta}
WHERE id = #{userId}
  AND follower_count + #{delta} >= 0
